	public DebuggerConsoleProvider(DebuggerConsolePlugin plugin) : base(plugin.getTool(), DebuggerResources.TITLE_PROVIDER_CONSOLE, plugin.getName())
    {
		this.plugin = plugin;
		this.progressListener = new ListenerForProgress();

		logTableModel = new LogTableModel(tool);

		tool.addPopupActionProvider(this);

		setIcon(DebuggerResources.ICON_PROVIDER_CONSOLE);
		setHelpLocation(DebuggerResources.HELP_PROVIDER_CONSOLE);
		setWindowMenuGroup(DebuggerPluginPackage.NAME);

		buildMainPanel();

		this.autoServiceWiring = AutoService.wireServicesConsumed(plugin, this);
		this.autoOptionsWiring = AutoOptions.wireOptions(plugin, this);

		setDefaultWindowPosition(WindowPosition.BOTTOM);
		setVisible(true);
		createActions();
	}

	protected void dispose() {
		tool.removePopupActionProvider(this);
	}

	protected void buildMainPanel() {
		logTable = new LogTable(logTableModel);
		logTable.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
		mainPanel.add(new JScrollPane(logTable));
		logFilterPanel = new(logTable, logTableModel);
		mainPanel.add(logFilterPanel, BorderLayout.NORTH);

		string namePrefix = "Debug Console";
		logTable.setAccessibleNamePrefix(namePrefix);
		logFilterPanel.setAccessibleNamePrefix(namePrefix);

		logTable.addMouseListener(new _Anon_MouseAdapter_1());
		logTable.addKeyListener(new _Anon_KeyAdapter_2());

		logTable.setPreferredRowHeight(ACTION_BUTTON_SIZE + 2);
	}

	protected bool activateSelectedRow() {
		LogRow<object> row = logFilterPanel.getSelectedItem();
		if (row == null) {
			return false;
		}
		return row.activated();
	}

	protected void createActions() {
		actionClear =
			ClearAction.builder(plugin).onAction(this.activatedClear).buildAndInstallLocal(this);
		actionSelectNone = SelectNoneAction.builder(plugin)
				.popupWhen(ctx => ctx.getSourceComponent() == logTable)
				.onAction(this.activatedSelectNone)
				.buildAndInstallLocal(this);
	}

	public void clear() {
		lock (buffer) {
			logTableModel.deleteItemsWith(r => !(r is MonitorLogRow));
			buffer.removeIf(r => !(r is MonitorLogRow));
		}
	}

	private void activatedClear(ActionContext ctx) {
		clear();
	}

	private void activatedSelectNone(ActionContext ctx) {
		logTable.clearSelection();
	}

	/* @Override */
	public ActionContext getActionContext(MouseEvent @event) {
		if (logTable.getSelectedRowCount() != 1) {
			return base.getActionContext(@event);
		}
		LogRow<object> sel = logFilterPanel.getSelectedItem();
		if (sel == null) {
			// I guess this can happen because of timing?
			return base.getActionContext(@event);
		}
		return sel.actionContext();
	}

	/* @AutoOptionConsumed(name = DebuggerResources.OPTION_NAME_LOG_BUFFER_LIMIT) */
	private void setLogBufferLimit(int logBufferLimit) {
		truncateLog();
	}

