	/* @AutoServiceConsumed */
	private void setProgressService(ProgressService progressService) {
		if (this.progressService != null) {
			this.progressService.removeProgressListener(progressListener);
		}
		this.progressService = progressService;
		if (this.progressService != null) {
			this.progressService.addProgressListener(progressListener);
		}
		resyncProgressRows();
	}

	private void resyncProgressRows() {
		lock (buffer) {
			logTableModel.deleteItemsWith(r => r is MonitorLogRow);
			if (progressService == null) {
				return;
			}
			foreach (MonitorReceiver monitor in progressService.getAllMonitors()) {
				if (!monitor.isValid()) {
					continue;
				}
				progressListener.monitorCreated(monitor);
			}
		}
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mousePressed(MouseEvent e) {
				if (e.getButton() == MouseEvent.BUTTON1 & e.getClickCount() == 2) {
					if (activateSelectedRow()) {
						e.consume();
					}
				}
			}
		
	}


	internal class _Anon_KeyAdapter_2 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent e) {
				if (e.getKeyCode() == KeyEvent.VK_ENTER) {
					if (activateSelectedRow()) {
						e.consume();
					}
				}
			}
		
	}

